{
 "command": "cat scripts/backfill_tax.py && ls scripts",
 "description": "Read the backfill script"
}

{
 "command": "echo \"DATABASE_URL set: ${DATABASE_URL:+yes}\"; echo \"BACKFILL_BATCH=${BACKFILL_BATCH}\"; env -u DATABASE_URL python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit $?\"",
 "description": "Check env and dry-run the backfill"
}

{
 "command": "cat src/billing/periods.py; git log --oneline -- src/billing/periods.py",
 "description": "Read the period helper"
}

{
 "command": "echo \"TZ=$TZ\"; date +%Z; grep -rn \"TZ\" README* docs Makefile 2>/dev/null | head; env -u DATABASE_URL TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit $?\"",
 "description": "Check timezone and retry dry run in UTC"
}
